<?php
class PlanillaModel {
private $db; public function __construct(PDO $db){$this->db=$db;}
public function datos():array{return ['personas'=>$this->db->query("SELECT p.id_persona,p.nombres,p.apellidos,GROUP_CONCAT(pp.tipo) perfiles FROM personas p JOIN persona_perfiles pp ON pp.id_persona=p.id_persona AND pp.estado='ACTIVO' LEFT JOIN vinculos_laborales v ON v.id_persona=p.id_persona AND v.estado='ACTIVO' WHERE p.estado='ACTIVO' AND v.id_vinculo IS NULL AND pp.tipo IN('DOCENTE','ADMINISTRATIVO') GROUP BY p.id_persona ORDER BY p.apellidos")->fetchAll(),'vinculos'=>$this->db->query("SELECT v.*,CONCAT(p.apellidos,', ',p.nombres) persona FROM vinculos_laborales v JOIN personas p ON p.id_persona=v.id_persona ORDER BY v.estado='ACTIVO' DESC,p.apellidos")->fetchAll(),'periodos'=>$this->db->query("SELECT * FROM periodos_pago ORDER BY fecha_inicio DESC")->fetchAll(),'reglas'=>$this->db->query("SELECT * FROM reglas_descuento WHERE estado='ACTIVO' ORDER BY evento,nombre")->fetchAll()];}
public function personasParaVinculo():array{return $this->db->query("SELECT p.id_persona,p.nombres,p.apellidos,p.codigo_trabajador,GROUP_CONCAT(pp.tipo) perfiles FROM personas p JOIN persona_perfiles pp ON pp.id_persona=p.id_persona AND pp.estado='ACTIVO' WHERE p.estado='ACTIVO' AND pp.tipo IN('DOCENTE','ADMINISTRATIVO') GROUP BY p.id_persona ORDER BY p.apellidos,p.nombres")->fetchAll();}
public function vinculo(array $d):void{
    $idPersona=(int)($d['id_persona']??0);$tipo=$d['tipo']??'';$inicio=$d['fecha_inicio']??'';$cargoNombre=trim($d['cargo']??'');
    if(!$idPersona||!in_array($tipo,['DOCENTE','ADMINISTRATIVO'],true)||!$inicio||!$cargoNombre)throw new InvalidArgumentException('Complete trabajador, tipo, cargo y fecha de inicio.');
    $this->db->beginTransaction();try{
        $cargo=$this->db->prepare('SELECT id_cargo FROM cargos WHERE nombre=? LIMIT 1');$cargo->execute([$cargoNombre]);$idCargo=(int)$cargo->fetchColumn();if(!$idCargo){$this->db->prepare("INSERT INTO cargos(nombre,estado) VALUES(?,'ACTIVO')")->execute([$cargoNombre]);$idCargo=(int)$this->db->lastInsertId();}
        $codigo=$this->db->prepare('SELECT codigo_trabajador FROM personas WHERE id_persona=? FOR UPDATE');$codigo->execute([$idPersona]);if(!$codigo->fetchColumn()){$anio=substr($inicio,0,4);$ultimo=$this->db->prepare("SELECT MAX(CAST(RIGHT(codigo_trabajador,4) AS UNSIGNED)) FROM personas WHERE codigo_trabajador LIKE ?");$ultimo->execute(['CS-'.$anio.'-%']);$nuevo='CS-'.$anio.'-'.str_pad((string)((int)$ultimo->fetchColumn()+1),4,'0',STR_PAD_LEFT);$this->db->prepare('UPDATE personas SET codigo_trabajador=? WHERE id_persona=?')->execute([$nuevo,$idPersona]);}
        $finAnterior=date('Y-m-d',strtotime($inicio.' -1 day'));$this->db->prepare("UPDATE vinculos_laborales SET estado='FINALIZADO',fecha_fin=COALESCE(fecha_fin,?) WHERE id_persona=? AND estado='ACTIVO'")->execute([$finAnterior,$idPersona]);
        $otro=$tipo==='DOCENTE'?'ADMINISTRATIVO':'DOCENTE';$this->db->prepare('UPDATE persona_perfiles SET estado="INACTIVO" WHERE id_persona=? AND tipo=?')->execute([$idPersona,$otro]);$this->db->prepare('INSERT INTO persona_perfiles(id_persona,tipo,estado,creado_en) VALUES(?,?,"ACTIVO",NOW()) ON DUPLICATE KEY UPDATE estado="ACTIVO"')->execute([$idPersona,$tipo]);
        $s=$this->db->prepare("INSERT INTO vinculos_laborales(id_persona,id_cargo,tipo,modalidad_pago,monto_base,fecha_inicio,fecha_fin,estado) VALUES(?,?,?,?,?,?,?,'ACTIVO')");$s->execute([$idPersona,$idCargo,$tipo,$d['modalidad_pago'],(float)$d['monto_base'],$inicio,$d['fecha_fin']?:null]);$this->db->commit();
    }catch(Throwable $e){$this->db->rollBack();throw $e;}
}
public function periodo(array $d):void{$s=$this->db->prepare("INSERT INTO periodos_pago(nombre,fecha_inicio,fecha_fin,estado) VALUES(?,?,?,'ABIERTO')");$s->execute([trim($d['nombre']),$d['fecha_inicio'],$d['fecha_fin']]);}
public function regla(array $d):void{$s=$this->db->prepare("INSERT INTO reglas_descuento(nombre,evento,formula,fecha_inicio,fecha_fin,estado) VALUES(?,?,?,? ,?,'ACTIVO')");$s->execute([trim($d['nombre']),$d['evento'],json_encode(['monto_unitario'=>(float)$d['monto_unitario']]),$d['fecha_inicio'],$d['fecha_fin']?:null]);}
private function concepto(string $evento):int{$tipo=$evento==='TARDANZA'?'TARDANZA':($evento==='FALTA'?'FALTA':'HORA');$s=$this->db->prepare("SELECT id_concepto_pago FROM conceptos_pago WHERE tipo=? AND naturaleza='DESCUENTO' LIMIT 1");$s->execute([$tipo]);$id=$s->fetchColumn();if($id)return (int)$id;$this->db->prepare("INSERT INTO conceptos_pago(nombre,naturaleza,tipo,estado) VALUES(?,'DESCUENTO',?,'ACTIVO')")->execute(['Descuento por '.strtolower(str_replace('_',' ',$evento)),$tipo]);return (int)$this->db->lastInsertId();}
public function calcular(int $id):int{$this->db->beginTransaction();try{$per=$this->db->prepare("SELECT * FROM periodos_pago WHERE id_periodo_pago=?");$per->execute([$id]);$p=$per->fetch();$q=$this->db->prepare("SELECT v.id_vinculo,v.id_persona,v.monto_base FROM vinculos_laborales v WHERE v.estado='ACTIVO' AND v.fecha_inicio<=? AND (v.fecha_fin IS NULL OR v.fecha_fin>=?)");$q->execute([$p['fecha_fin'],$p['fecha_inicio']]);$i=$this->db->prepare("INSERT INTO planilla_detalles(id_periodo_pago,id_vinculo,monto_base,bonificaciones,descuentos,monto_pagar,estado) VALUES(?,?,?,0,0,?,'CALCULADO') ON DUPLICATE KEY UPDATE monto_base=VALUES(monto_base),bonificaciones=0,descuentos=0,monto_pagar=VALUES(monto_pagar),calculado_en=NOW()");$n=0;foreach($q->fetchAll() as $v){$i->execute([$id,$v['id_vinculo'],$v['monto_base'],$v['monto_base']]);$n++;}$this->db->prepare("DELETE pc FROM planilla_detalle_conceptos pc JOIN planilla_detalles pd ON pd.id_planilla_detalle=pc.id_planilla_detalle WHERE pd.id_periodo_pago=?")->execute([$id]);$r=$this->db->prepare("SELECT * FROM reglas_descuento WHERE estado='ACTIVO' AND fecha_inicio<=? AND (fecha_fin IS NULL OR fecha_fin>=?)");$r->execute([$p['fecha_fin'],$p['fecha_inicio']]);$detalle=$this->db->prepare("SELECT pd.id_planilla_detalle,pd.monto_base,v.id_persona FROM planilla_detalles pd JOIN vinculos_laborales v ON v.id_vinculo=pd.id_vinculo WHERE pd.id_periodo_pago=?");$detalle->execute([$id]);foreach($detalle->fetchAll() as $d){$des=0;foreach($r->fetchAll() as $reg){$f=json_decode($reg['formula'],true);$campo=$reg['evento']==='TARDANZA'?'COALESCE(SUM(minutos_tardanza),0)':($reg['evento']==='FALTA'?"COALESCE(SUM(estado='FALTA'),0)":'0');$a=$this->db->prepare("SELECT $campo FROM asistencias_diarias WHERE id_persona=? AND fecha BETWEEN ? AND ?");$a->execute([$d['id_persona'],$p['fecha_inicio'],$p['fecha_fin']]);$cant=(float)$a->fetchColumn();$imp=round($cant*(float)($f['monto_unitario']??0),2);if($imp>0){$this->db->prepare("INSERT INTO planilla_detalle_conceptos(id_planilla_detalle,id_concepto_pago,id_regla,cantidad,importe,explicacion) VALUES(?,?,?,?,?,?)")->execute([$d['id_planilla_detalle'],$this->concepto($reg['evento']),$reg['id_regla'],$cant,-$imp,json_encode(['evento'=>$reg['evento'],'monto_unitario'=>$f['monto_unitario']])]);$des+=$imp;}}$this->db->prepare("UPDATE planilla_detalles SET descuentos=?,monto_pagar=? WHERE id_planilla_detalle=?")->execute([$des,max(0,(float)$d['monto_base']-$des),$d['id_planilla_detalle']]);}$this->db->prepare("UPDATE periodos_pago SET estado='CALCULADO' WHERE id_periodo_pago=?")->execute([$id]);$this->db->commit();return $n;}catch(Throwable $e){$this->db->rollBack();throw $e;}}
}
